#include "planner.h"
typedef struct {
    uint64_t *bits;
    int size, words, count;
} Mutex;
static Mutex mutex_create(int size) {
    Mutex out = {0};
    out.size = size;
    out.words = (size + 63) / 64;
    out.bits = allocate((size_t)size * (size_t)out.words * sizeof *out.bits);
    return out;
}
static bool mutex_has(const Mutex *mutex, int a, int b) {
    return a != b && (mutex->bits[(size_t)a * (size_t)mutex->words + (size_t)b / 64] &
                      (UINT64_C(1) << (b % 64)));
}
static void mutex_put(Mutex *mutex, int a, int b) {
    if (a == b || mutex_has(mutex, a, b))
        return;
    mutex->bits[(size_t)a * (size_t)mutex->words + (size_t)b / 64] |= UINT64_C(1) << (b % 64);
    mutex->bits[(size_t)b * (size_t)mutex->words + (size_t)a / 64] |= UINT64_C(1) << (a % 64);
    ++mutex->count;
}
static bool mutex_compatible(const Mutex *mutex, State facts) {
    for (int i = 0; i < 256; ++i)
        if (state_has(facts, i))
            for (int j = i + 1; j < 256; ++j)
                if (state_has(facts, j) && mutex_has(mutex, i, j))
                    return false;
    return true;
}
void layers_push(Layers *layers, IntList layer) {
    if (layers->count == layers->capacity) {
        layers->capacity = layers->capacity ? layers->capacity * 2 : 8;
        layers->data = resize(layers->data, (size_t)layers->capacity * sizeof *layers->data);
    }
    layers->data[layers->count++] = layer;
}
void layers_free(Layers *layers) {
    for (int i = 0; i < layers->count; ++i)
        int_free(&layers->data[i]);
    free(layers->data);
    *layers = (Layers){0};
}
void graph_result_free(GraphPlanResult *result) {
    int_free(&result->plan);
    layers_free(&result->layers);
    lines_free(&result->logs);
}
typedef struct {
    GraphElement *data;
    int count;
} ActionLevel;
typedef struct {
    const GraphElement *actions;
    int action_count;
    State facts[31];
    Mutex fact_mutex[31];
    ActionLevel elements[30];
    Mutex action_mutex[30];
    StateTable memo[31];
    GraphPlanResult result;
} PlanningGraph;
static bool extract(PlanningGraph *graph, int level, State goals, Layers *out);
static int compare_ints(const void *left, const void *right) {
    int a = *(const int *)left, b = *(const int *)right;
    return (a > b) - (a < b);
}
static bool assign(PlanningGraph *graph, int level, const IntList *goals, int at, IntList *chosen,
                   Layers *out) {
    const ActionLevel *entries = &graph->elements[level - 1];
    const Mutex *mutex = &graph->action_mutex[level - 1];
    State covered = {0};
    for (int i = 0; i < chosen->count; ++i)
        covered = state_union(covered, entries->data[chosen->data[i]].add);
    while (at < goals->count && state_has(covered, goals->data[at]))
        ++at;
    if (at == goals->count) {
        State pre = {0};
        for (int i = 0; i < chosen->count; ++i)
            pre = state_union(pre, entries->data[chosen->data[i]].pre);
        if (!extract(graph, level - 1, pre, out))
            return false;
        IntList layer = {0};
        for (int i = 0; i < chosen->count; ++i) {
            int action = entries->data[chosen->data[i]].action;
            if (action >= 0)
                int_push(&layer, action);
        }
        if (layer.count > 1)
            qsort(layer.data, (size_t)layer.count, sizeof *layer.data, compare_ints);
        layers_push(out, layer);
        return true;
    }
    int fact = goals->data[at];
    IntList achievers = {0};
    for (int i = 0; i < entries->count; ++i)
        if (entries->data[i].action < 0 && entries->data[i].fact == fact)
            int_push(&achievers, i);
    for (int i = 0; i < entries->count; ++i)
        if (entries->data[i].action >= 0 && state_has(entries->data[i].add, fact))
            int_push(&achievers, i);
    for (int i = 0; i < achievers.count; ++i) {
        int index = achievers.data[i];
        bool compatible = true;
        for (int j = 0; j < chosen->count; ++j)
            if (mutex_has(mutex, index, chosen->data[j])) {
                compatible = false;
                break;
            }
        if (!compatible)
            continue;
        ++graph->result.tried;
        int_push(chosen, index);
        bool success = assign(graph, level, goals, at + 1, chosen, out);
        --chosen->count;
        if (success) {
            int_free(&achievers);
            return true;
        }
    }
    int_free(&achievers);
    return false;
}
static bool extract(PlanningGraph *graph, int level, State goals, Layers *out) {
    if (!level)
        return true;
    if (state_table_get(&graph->memo[level], goals, NULL)) {
        ++graph->result.memo_hits;
        return false;
    }
    ++graph->result.searched;
    IntList numbers = state_numbers(goals), chosen = {0};
    bool success = assign(graph, level, &numbers, 0, &chosen, out);
    int_free(&numbers);
    int_free(&chosen);
    if (!success)
        state_table_set(&graph->memo[level], goals, 0);
    return success;
}
static void expand(PlanningGraph *graph, int level) {
    State previous = graph->facts[level];
    const Mutex *previous_mutex = &graph->fact_mutex[level];
    ActionLevel entries = {0};
    entries.data =
        allocate((size_t)(graph->action_count + state_count(previous)) * sizeof *entries.data);
    for (int i = 0; i < graph->action_count; ++i) {
        GraphElement action = graph->actions[i];
        if (state_contains(previous, action.pre) && mutex_compatible(previous_mutex, action.pre))
            entries.data[entries.count++] = action;
    }
    int real = entries.count;
    for (int fact = 0; fact < 256; ++fact)
        if (state_has(previous, fact)) {
            State one = {0};
            state_put(&one, fact);
            entries.data[entries.count++] = (GraphElement){-1, fact, one, one, {{0}}};
        }
    Mutex mutex = mutex_create(entries.count);
    for (int i = 0; i < entries.count; ++i)
        for (int j = i + 1; j < entries.count; ++j) {
            const GraphElement *a = &entries.data[i], *b = &entries.data[j];
            bool exclusive = state_intersects(a->del, state_union(b->pre, b->add)) ||
                             state_intersects(b->del, state_union(a->pre, a->add));
            if (!exclusive)
                for (int p = 0; p < 256 && !exclusive; ++p)
                    if (state_has(a->pre, p))
                        for (int q = 0; q < 256; ++q)
                            if (state_has(b->pre, q) && mutex_has(previous_mutex, p, q)) {
                                exclusive = true;
                                break;
                            }
            if (exclusive)
                mutex_put(&mutex, i, j);
        }
    lines_push(&graph->result.logs, format_text("action level %d: actions=%d noops=%d mutexes=%d",
                                                level, real, state_count(previous), mutex.count));
    State next = {0};
    IntList achievers[256] = {0};
    for (int i = 0; i < entries.count; ++i) {
        next = state_union(next, entries.data[i].add);
        for (int fact = 0; fact < 256; ++fact)
            if (state_has(entries.data[i].add, fact))
                int_push(&achievers[fact], i);
    }
    Mutex next_mutex = mutex_create(256);
    for (int p = 0; p < 256; ++p)
        if (state_has(next, p))
            for (int q = p + 1; q < 256; ++q)
                if (state_has(next, q)) {
                    bool exclusive = true;
                    for (int x = 0; x < achievers[p].count && exclusive; ++x)
                        for (int y = 0; y < achievers[q].count; ++y)
                            if (!mutex_has(&mutex, achievers[p].data[x], achievers[q].data[y])) {
                                exclusive = false;
                                break;
                            }
                    if (exclusive)
                        mutex_put(&next_mutex, p, q);
                }
    for (int i = 0; i < 256; ++i)
        int_free(&achievers[i]);
    graph->elements[level] = entries;
    graph->action_mutex[level] = mutex;
    graph->facts[level + 1] = next;
    graph->fact_mutex[level + 1] = next_mutex;
}
GraphPlanResult graph_plan(const GraphElement *actions, int action_count, State initial, State goal,
                           int limit) {
    PlanningGraph *graph = allocate(sizeof *graph);
    graph->actions = actions;
    graph->action_count = action_count;
    graph->facts[0] = initial;
    graph->fact_mutex[0] = mutex_create(256);
    int last = 0;
    for (int level = 0;; ++level) {
        last = level;
        State facts = graph->facts[level];
        const Mutex *mutex = &graph->fact_mutex[level];
        lines_push(&graph->result.logs, format_text("fact level %d: facts=%d mutexes=%d", level,
                                                    state_count(facts), mutex->count));
        bool attempted = state_contains(facts, goal) && mutex_compatible(mutex, goal);
        if (attempted) {
            Value searched = graph->result.searched, hits = graph->result.memo_hits;
            Layers layers = {0};
            bool success = extract(graph, level, goal, &layers);
            lines_push(&graph->result.logs,
                       format_text("extract level %d: %s searched=%lld memo_hits=%lld", level,
                                   success ? "success" : "fail", graph->result.searched - searched,
                                   graph->result.memo_hits - hits));
            if (success) {
                graph->result.status = "solved";
                graph->result.layers = layers;
                for (int i = 0; i < layers.count; ++i)
                    for (int j = 0; j < layers.data[i].count; ++j)
                        int_push(&graph->result.plan, layers.data[i].data[j]);
                break;
            }
            layers_free(&layers);
        } else if (level && state_count(facts) == state_count(graph->facts[level - 1]) &&
                   mutex->count == graph->fact_mutex[level - 1].count) {
            graph->result.status = "unreachable";
            break;
        }
        if (level == limit) {
            graph->result.status = "level limit";
            break;
        }
        expand(graph, level);
    }
    for (int i = 0; i <= last; ++i) {
        free(graph->fact_mutex[i].bits);
        state_table_free(&graph->memo[i]);
        if (i < last) {
            free(graph->elements[i].data);
            free(graph->action_mutex[i].bits);
        }
    }
    GraphPlanResult out = graph->result;
    free(graph);
    return out;
}

#include "planner.h"
bool state_has(State state, int fact) {
    return (state.words[fact / 64] & (UINT64_C(1) << (fact % 64))) != 0;
}
void state_put(State *state, int fact) { state->words[fact / 64] |= UINT64_C(1) << (fact % 64); }
State state_union(State a, State b) {
    for (int i = 0; i < 4; ++i)
        a.words[i] |= b.words[i];
    return a;
}
State state_without(State a, State b) {
    for (int i = 0; i < 4; ++i)
        a.words[i] &= ~b.words[i];
    return a;
}
State state_intersection(State a, State b) {
    for (int i = 0; i < 4; ++i)
        a.words[i] &= b.words[i];
    return a;
}
bool state_contains(State a, State b) {
    for (int i = 0; i < 4; ++i)
        if ((a.words[i] & b.words[i]) != b.words[i])
            return false;
    return true;
}
bool state_intersects(State a, State b) {
    for (int i = 0; i < 4; ++i)
        if (a.words[i] & b.words[i])
            return true;
    return false;
}
bool state_equal(State a, State b) {
    for (int i = 0; i < 4; ++i)
        if (a.words[i] != b.words[i])
            return false;
    return true;
}
IntList state_numbers(State state) {
    IntList out = {0};
    for (int i = 0; i < 256; ++i)
        if (state_has(state, i))
            int_push(&out, i);
    return out;
}
int state_count(State state) {
    int count = 0;
    for (int i = 0; i < 4; ++i) {
        uint64_t word = state.words[i];
        while (word) {
            word &= word - 1;
            ++count;
        }
    }
    return count;
}
uint64_t state_hash(State state) {
    uint64_t hash = UINT64_C(1469598103934665603);
    for (int i = 0; i < 4; ++i) {
        hash ^= state.words[i];
        hash *= UINT64_C(1099511628211);
    }
    return hash;
}
static void state_table_rehash(StateTable *table, int size) {
    free(table->slots);
    table->slots = allocate((size_t)size * sizeof *table->slots);
    table->slot_count = size;
    for (int i = 0; i < table->count; ++i) {
        int slot = (int)(state_hash(table->data[i].state) & (uint64_t)(size - 1));
        while (table->slots[slot])
            slot = (slot + 1) & (size - 1);
        table->slots[slot] = i + 1;
    }
}
bool state_table_get(const StateTable *table, State state, Value *value) {
    if (!table->slot_count)
        return false;
    int slot = (int)(state_hash(state) & (uint64_t)(table->slot_count - 1));
    while (table->slots[slot]) {
        int index = table->slots[slot] - 1;
        if (state_equal(table->data[index].state, state)) {
            if (value)
                *value = table->data[index].value;
            return true;
        }
        slot = (slot + 1) & (table->slot_count - 1);
    }
    return false;
}
void state_table_set(StateTable *table, State state, Value value) {
    if (!table->slot_count || (table->count + 1) * 10 > table->slot_count * 7)
        state_table_rehash(table, table->slot_count ? table->slot_count * 2 : 128);
    int slot = (int)(state_hash(state) & (uint64_t)(table->slot_count - 1));
    while (table->slots[slot]) {
        int index = table->slots[slot] - 1;
        if (state_equal(table->data[index].state, state)) {
            table->data[index].value = value;
            return;
        }
        slot = (slot + 1) & (table->slot_count - 1);
    }
    if (table->count == table->capacity) {
        table->capacity = table->capacity ? table->capacity * 2 : 64;
        table->data = resize(table->data, (size_t)table->capacity * sizeof *table->data);
    }
    table->slots[slot] = table->count + 1;
    table->data[table->count++] = (StateEntry){state, value};
}
void state_table_free(StateTable *table) {
    free(table->data);
    free(table->slots);
    *table = (StateTable){0};
}
int typed_find(const TypedList *types, int name) {
    for (int i = 0; i < types->count; ++i)
        if (types->data[i].name == name)
            return types->data[i].type;
    return -1;
}
int predicate_index(const Domain *domain, int name) {
    for (int i = 0; i < domain->predicate_count; ++i)
        if (domain->predicates[i].name == name)
            return i;
    return -1;
}
bool subtype(const Domain *domain, int type, int expected) {
    int object = symbol("object");
    while (type != expected) {
        if (type == object)
            return false;
        type = typed_find(&domain->parents, type);
    }
    return true;
}
void classify(Domain *domain) {
    memset(domain->fluent, 0, sizeof domain->fluent);
    for (int i = 0; i < domain->action_count; ++i)
        for (int j = 0; j < domain->actions[i].effects.count; ++j)
            domain->fluent[predicate_index(
                domain, get_atom(domain->actions[i].effects.data[j].atom)->predicate)] = true;
}
int substitute_atom(int id, const TypedList *assignment) {
    Atom atom = *get_atom(id);
    IntList terms = {0};
    for (int i = 0; i < atom.terms.count; ++i)
        int_push(&terms, typed_find(assignment, atom.terms.data[i]));
    int result = intern_atom(atom.predicate, &terms);
    int_free(&terms);
    return result;
}
IntList objects_of_type(const Domain *domain, const Problem *problem, int type) {
    IntList out = {0};
    for (int i = 0; i < problem->objects.count; ++i)
        if (subtype(domain, problem->objects.data[i].type, type))
            int_push(&out, problem->objects.data[i].name);
    return out;
}
typedef struct {
    int schema;
    IntList arguments, pre, neg, add, del;
    bool reachable;
} Candidate;
typedef struct {
    const Domain *domain;
    const Problem *problem;
    GroundProblem *ground;
    Candidate *candidates;
    int count, capacity;
    IntList *choices, arguments;
    TypedList assignment;
    int schema;
} Grounding;
static void candidate_free(Candidate *candidate) {
    int_free(&candidate->arguments);
    int_free(&candidate->pre);
    int_free(&candidate->neg);
    int_free(&candidate->add);
    int_free(&candidate->del);
}
static void enumerate(Grounding *work, int at) {
    const Schema *schema = &work->domain->actions[work->schema];
    if (at < schema->parameters.count) {
        for (int i = 0; i < work->choices[at].count; ++i) {
            int object = work->choices[at].data[i];
            work->arguments.data[at] = object;
            work->assignment.data[at].type = object;
            enumerate(work, at + 1);
        }
        return;
    }
    Candidate candidate = {0};
    candidate.schema = work->schema;
    candidate.arguments = int_copy(&work->arguments);
    for (int i = 0; i < schema->conditions.count; ++i) {
        Literal literal = schema->conditions.data[i];
        int id = substitute_atom(literal.atom, &work->assignment);
        const Atom *atom = get_atom(id);
        int predicate = predicate_index(work->domain, atom->predicate);
        if (!strcmp(symbol_name(atom->predicate), "=") || !work->domain->fluent[predicate]) {
            bool truth = !strcmp(symbol_name(atom->predicate), "=")
                             ? atom->terms.data[0] == atom->terms.data[1]
                             : int_has(&work->problem->initial, id);
            if (truth == literal.negative) {
                candidate_free(&candidate);
                return;
            }
        } else
            int_add(literal.negative ? &candidate.neg : &candidate.pre, id);
    }
    for (int i = 0; i < schema->effects.count; ++i) {
        Literal literal = schema->effects.data[i];
        int_add(literal.negative ? &candidate.del : &candidate.add,
                substitute_atom(literal.atom, &work->assignment));
    }
    int kept = 0;
    for (int i = 0; i < candidate.del.count; ++i)
        if (!int_has(&candidate.add, candidate.del.data[i]))
            candidate.del.data[kept++] = candidate.del.data[i];
    candidate.del.count = kept;
    if (work->count == work->capacity) {
        work->capacity = work->capacity ? work->capacity * 2 : 128;
        work->candidates =
            resize(work->candidates, (size_t)work->capacity * sizeof *work->candidates);
    }
    work->candidates[work->count++] = candidate;
    ++work->ground->counts[work->schema].candidates;
}
static bool contains_atoms(const IntList *set, const IntList *required) {
    for (int i = 0; i < required->count; ++i)
        if (!int_has(set, required->data[i]))
            return false;
    return true;
}
static State to_state(const GroundProblem *ground, const IntList *atoms) {
    State out = {0};
    for (int i = 0; i < ground->facts.count; ++i)
        if (int_has(atoms, ground->facts.data[i]))
            state_put(&out, i);
    return out;
}
static int object_number(const Problem *problem, int name) {
    for (int i = 0; i < problem->objects.count; ++i)
        if (problem->objects.data[i].name == name)
            return i;
    return -1;
}
static bool fact_before(const Domain *domain, const Problem *problem, int left, int right) {
    const Atom *a = get_atom(left), *b = get_atom(right);
    int ap = predicate_index(domain, a->predicate), bp = predicate_index(domain, b->predicate);
    if (ap != bp)
        return ap < bp;
    for (int i = 0; i < a->terms.count; ++i) {
        int av = object_number(problem, a->terms.data[i]),
            bv = object_number(problem, b->terms.data[i]);
        if (av != bv)
            return av < bv;
    }
    return false;
}
GroundProblem ground(const Domain *domain, const Problem *problem) {
    GroundProblem out = {0};
    out.domain = domain;
    out.problem = problem;
    IntList reachable = {0};
    for (int i = 0; i < problem->initial.count; ++i) {
        int id = problem->initial.data[i];
        if (domain->fluent[predicate_index(domain, get_atom(id)->predicate)])
            int_add(&reachable, id);
        else
            ++out.static_facts;
    }
    Grounding work = {0};
    work.domain = domain;
    work.problem = problem;
    work.ground = &out;
    for (int i = 0; i < domain->action_count; ++i) {
        work.schema = i;
        const Schema *schema = &domain->actions[i];
        out.counts[i].assignments = 1;
        work.choices = allocate((size_t)schema->parameters.count * sizeof *work.choices);
        work.assignment = (TypedList){0};
        work.assignment.count = work.assignment.capacity = schema->parameters.count;
        work.assignment.data =
            allocate((size_t)work.assignment.count * sizeof *work.assignment.data);
        work.arguments = (IntList){0};
        for (int j = 0; j < schema->parameters.count; ++j) {
            work.choices[j] = objects_of_type(domain, problem, schema->parameters.data[j].type);
            out.counts[i].assignments *= work.choices[j].count;
            work.assignment.data[j] = (Typed){schema->parameters.data[j].name, 0};
            int_push(&work.arguments, 0);
        }
        enumerate(&work, 0);
        for (int j = 0; j < schema->parameters.count; ++j)
            int_free(&work.choices[j]);
        free(work.choices);
        free(work.assignment.data);
        int_free(&work.arguments);
    }
    out.candidate_count = work.count;
    for (;;) {
        bool changed = false;
        for (int i = 0; i < work.count; ++i) {
            Candidate *candidate = &work.candidates[i];
            if (!candidate->reachable && contains_atoms(&reachable, &candidate->pre)) {
                candidate->reachable = true;
                changed = true;
                for (int j = 0; j < candidate->add.count; ++j)
                    int_add(&reachable, candidate->add.data[j]);
            }
        }
        if (!changed)
            break;
    }
    out.facts = reachable;
    for (int i = 1; i < out.facts.count; ++i) {
        int value = out.facts.data[i], j = i;
        while (j && fact_before(domain, problem, value, out.facts.data[j - 1])) {
            out.facts.data[j] = out.facts.data[j - 1];
            --j;
        }
        out.facts.data[j] = value;
    }
    out.initial = to_state(&out, &problem->initial);
    for (int i = 0; i < work.count; ++i) {
        Candidate *candidate = &work.candidates[i];
        if (candidate->reachable) {
            GroundAction *action = &out.actions[out.action_count++];
            *action = (GroundAction){candidate->schema,
                                     candidate->arguments,
                                     domain->actions[candidate->schema].cost,
                                     to_state(&out, &candidate->pre),
                                     to_state(&out, &candidate->neg),
                                     to_state(&out, &candidate->add),
                                     to_state(&out, &candidate->del)};
            candidate->arguments = (IntList){0};
            ++out.counts[candidate->schema].reachable;
        }
        candidate_free(candidate);
    }
    free(work.candidates);
    for (int i = 0; i < problem->goals.count; ++i) {
        int id = problem->goals.data[i], fact = -1;
        for (int j = 0; j < out.facts.count; ++j)
            if (out.facts.data[j] == id) {
                fact = j;
                break;
            }
        if (fact >= 0)
            state_put(&out.goal, fact);
        else if (domain->fluent[predicate_index(domain, get_atom(id)->predicate)] ||
                 !int_has(&problem->initial, id))
            int_push(&out.unreachable, id);
    }
    return out;
}
void ground_free(GroundProblem *ground) {
    int_free(&ground->facts);
    int_free(&ground->unreachable);
    for (int i = 0; i < ground->action_count; ++i)
        int_free(&ground->actions[i].arguments);
    for (int i = 0; i < ground->cache_count; ++i) {
        Heuristic *heuristic = ground->cache[i].heuristic;
        int_free(&heuristic->relaxed);
        int_free(&heuristic->helpful);
        free(heuristic);
    }
    free(ground->cache);
    free(ground->cache_slots);
}

#include "planner.h"
Value heuristic_value(const Heuristic *heuristic, const char *name) {
    if (!strcmp(name, "none"))
        return 0;
    if (!strcmp(name, "goalcount"))
        return heuristic->goalcount;
    if (!strcmp(name, "hmax"))
        return heuristic->hmax;
    if (!strcmp(name, "hadd"))
        return heuristic->hadd;
    if (!strcmp(name, "ff"))
        return heuristic->ff;
    return heuristic->lmcount;
}
static Value aggregate(const Value *costs, State required, bool sum) {
    Value out = 0;
    for (int i = 0; i < 100; ++i)
        if (state_has(required, i)) {
            if (costs[i] == INFINITY_VALUE)
                return INFINITY_VALUE;
            if (sum)
                out += costs[i];
            else if (costs[i] > out)
                out = costs[i];
        }
    return out;
}
static void relaxed_costs(const GroundProblem *ground, State state, bool sum, Value *costs) {
    for (int i = 0; i < ground->facts.count; ++i)
        costs[i] = state_has(state, i) ? 0 : INFINITY_VALUE;
    for (;;) {
        bool changed = false;
        for (int i = 0; i < ground->action_count; ++i) {
            const GroundAction *action = &ground->actions[i];
            Value pre = aggregate(costs, action->pre, sum);
            if (pre == INFINITY_VALUE)
                continue;
            Value value = action->cost + pre;
            for (int fact = 0; fact < ground->facts.count; ++fact)
                if (state_has(action->add, fact) && value < costs[fact]) {
                    costs[fact] = value;
                    changed = true;
                }
        }
        if (!changed)
            return;
    }
}
static State reachable_without(const GroundProblem *ground, State state, int forbidden) {
    for (;;) {
        State previous = state;
        for (int i = 0; i < ground->action_count; ++i) {
            const GroundAction *action = &ground->actions[i];
            if (!state_has(action->add, forbidden) && state_contains(state, action->pre))
                state = state_union(state, action->add);
        }
        if (state_equal(previous, state))
            return state;
    }
}
static void require_fact(const GroundProblem *ground, State state, const int *best, bool *selected,
                         int fact) {
    if (state_has(state, fact))
        return;
    int action = best[fact];
    if (selected[action])
        return;
    selected[action] = true;
    for (int pre = 0; pre < ground->facts.count; ++pre)
        if (state_has(ground->actions[action].pre, pre))
            require_fact(ground, state, best, selected, pre);
}
static void cache_rehash(GroundProblem *ground, int size) {
    free(ground->cache_slots);
    ground->cache_slots = allocate((size_t)size * sizeof *ground->cache_slots);
    ground->cache_slot_count = size;
    for (int i = 0; i < ground->cache_count; ++i) {
        int slot = (int)(state_hash(ground->cache[i].state) & (uint64_t)(size - 1));
        while (ground->cache_slots[slot])
            slot = (slot + 1) & (size - 1);
        ground->cache_slots[slot] = i + 1;
    }
}
Heuristic *heuristics(GroundProblem *ground, State state) {
    if (!ground->cache_slot_count || (ground->cache_count + 1) * 10 > ground->cache_slot_count * 7)
        cache_rehash(ground, ground->cache_slot_count ? ground->cache_slot_count * 2 : 128);
    int slot = (int)(state_hash(state) & (uint64_t)(ground->cache_slot_count - 1));
    while (ground->cache_slots[slot]) {
        int index = ground->cache_slots[slot] - 1;
        if (state_equal(ground->cache[index].state, state))
            return ground->cache[index].heuristic;
        slot = (slot + 1) & (ground->cache_slot_count - 1);
    }
    Heuristic *out = allocate(sizeof *out);
    out->goalcount = state_count(state_without(ground->goal, state));
    Value cmax[100] = {0}, cadd[100] = {0};
    relaxed_costs(ground, state, false, cmax);
    relaxed_costs(ground, state, true, cadd);
    out->hmax = aggregate(cmax, ground->goal, false);
    out->hadd = aggregate(cadd, ground->goal, true);
    IntList achievers[100] = {0};
    for (int i = 0; i < ground->action_count; ++i)
        for (int fact = 0; fact < ground->facts.count; ++fact)
            if (state_has(ground->actions[i].add, fact))
                int_push(&achievers[fact], i);
    if (out->hadd == INFINITY_VALUE)
        out->ff = INFINITY_VALUE;
    else {
        int best[100];
        for (int fact = 0; fact < ground->facts.count; ++fact) {
            best[fact] = -1;
            if (state_has(state, fact) || cadd[fact] == INFINITY_VALUE)
                continue;
            Value minimum = INFINITY_VALUE;
            for (int j = 0; j < achievers[fact].count; ++j) {
                int index = achievers[fact].data[j];
                const GroundAction *action = &ground->actions[index];
                Value pre = aggregate(cadd, action->pre, true);
                if (pre != INFINITY_VALUE && action->cost + pre < minimum) {
                    minimum = action->cost + pre;
                    best[fact] = index;
                }
            }
        }
        bool selected[300] = {0};
        for (int fact = 0; fact < ground->facts.count; ++fact)
            if (state_has(ground->goal, fact))
                require_fact(ground, state, best, selected, fact);
        for (int i = 0; i < ground->action_count; ++i)
            if (selected[i]) {
                int_push(&out->relaxed, i);
                out->ff += ground->actions[i].cost;
                if (applicable(&ground->actions[i], state))
                    int_push(&out->helpful, i);
            }
    }
    int fact_levels[100], action_levels[300];
    for (int i = 0; i < ground->facts.count; ++i)
        fact_levels[i] = state_has(state, i) ? 0 : -1;
    for (int i = 0; i < ground->action_count; ++i)
        action_levels[i] = -1;
    for (int level = 0;; ++level) {
        bool changed = false;
        for (int i = 0; i < ground->action_count; ++i)
            if (action_levels[i] < 0) {
                const GroundAction *action = &ground->actions[i];
                bool ready = true;
                for (int pre = 0; pre < ground->facts.count; ++pre)
                    if (state_has(action->pre, pre) &&
                        (fact_levels[pre] < 0 || fact_levels[pre] > level)) {
                        ready = false;
                        break;
                    }
                if (!ready)
                    continue;
                action_levels[i] = level;
                for (int fact = 0; fact < ground->facts.count; ++fact)
                    if (state_has(action->add, fact) && fact_levels[fact] < 0) {
                        fact_levels[fact] = level + 1;
                        changed = true;
                    }
            }
        if (!changed)
            break;
    }
    bool unreachable = false;
    for (int fact = 0; fact < ground->facts.count; ++fact)
        if (state_has(ground->goal, fact) && fact_levels[fact] < 0)
            unreachable = true;
    if (unreachable)
        out->lmcount = INFINITY_VALUE;
    else {
        out->landmarks = state_without(ground->goal, state);
        int verified[100];
        for (int i = 0; i < 100; ++i)
            verified[i] = -1;
        for (;;) {
            State previous = out->landmarks;
            for (int fact = 0; fact < ground->facts.count; ++fact)
                if (state_has(previous, fact)) {
                    State common = {0};
                    bool first = true;
                    for (int j = 0; j < achievers[fact].count; ++j) {
                        int index = achievers[fact].data[j];
                        if (action_levels[index] == fact_levels[fact] - 1) {
                            common = first ? ground->actions[index].pre
                                           : state_intersection(common, ground->actions[index].pre);
                            first = false;
                        }
                    }
                    common = state_without(common, state);
                    for (int candidate = 0; candidate < ground->facts.count; ++candidate)
                        if (state_has(common, candidate) && !state_has(out->landmarks, candidate)) {
                            if (verified[candidate] < 0)
                                verified[candidate] = !state_contains(
                                    reachable_without(ground, state, candidate), ground->goal);
                            if (verified[candidate])
                                state_put(&out->landmarks, candidate);
                        }
                }
            if (state_equal(previous, out->landmarks))
                break;
        }
        out->lmcount = state_count(out->landmarks);
    }
    for (int i = 0; i < ground->facts.count; ++i)
        int_free(&achievers[i]);
    if (ground->cache_count == ground->cache_capacity) {
        ground->cache_capacity = ground->cache_capacity ? ground->cache_capacity * 2 : 64;
        ground->cache =
            resize(ground->cache, (size_t)ground->cache_capacity * sizeof *ground->cache);
    }
    ground->cache_slots[slot] = ground->cache_count + 1;
    ground->cache[ground->cache_count++] = (HeuristicEntry){state, out};
    return out;
}

#include "planner.h"
static const char *heuristic_names[] = {"goalcount", "hmax", "hadd", "ff", "lmcount"};
static void append_owned(TextLines *lines, TextLines *from) {
    for (int i = 0; i < from->count; ++i)
        lines_push(lines, from->data[i]);
    free(from->data);
    *from = (TextLines){0};
}
static char *heading(const char *name, const TextLines *items) {
    char *joined = items->count ? join_texts(items, " ") : copy_text("-");
    char *out = format_text("%s %s", name, joined);
    free(joined);
    return out;
}
static char *number_list(State state) {
    TextLines items = {0};
    for (int i = 0; i < 256; ++i)
        if (state_has(state, i))
            lines_push(&items, format_text("%d", i));
    char *out = items.count ? join_texts(&items, ",") : copy_text("-");
    lines_free(&items);
    return out;
}
static char *step_text(const Step *step) {
    return atom_text(intern_atom(step->name, &step->arguments));
}
static char *action_text(const GroundProblem *ground, int index) {
    const GroundAction *action = &ground->actions[index];
    return atom_text(intern_atom(ground->domain->actions[action->schema].name, &action->arguments));
}
static TextLines action_texts(const GroundProblem *ground, const IntList *plan) {
    TextLines out = {0};
    for (int i = 0; i < plan->count; ++i)
        lines_push(&out, action_text(ground, plan->data[i]));
    return out;
}
static Settings read_settings(void) {
    Settings out = {0};
    TextLines lines = read_lines("input/params.txt");
    for (int i = 0; i < lines.count; ++i) {
        if (!lines.data[i][0] || lines.data[i][0] == '#')
            continue;
        IntList words = split_words(lines.data[i]);
        const char *kind = symbol_name(words.data[0]);
        if (!strcmp(kind, "budget"))
            out.budget = atoi(symbol_name(words.data[1]));
        else if (!strcmp(kind, "weight"))
            out.weight = atoi(symbol_name(words.data[1]));
        else if (!strcmp(kind, "graphplan"))
            out.level_limit = atoi(symbol_name(words.data[1]));
        else {
            SearchSettings settings = {symbol_name(words.data[1]), symbol_name(words.data[2])};
            if (!strcmp(kind, "run"))
                out.runs[out.run_count++] = settings;
            else
                out.repair = settings;
        }
        int_free(&words);
    }
    lines_free(&lines);
    return out;
}
static void steps_push(StepList *list, Step step) {
    if (list->count == list->capacity) {
        list->capacity = list->capacity ? list->capacity * 2 : 8;
        list->data = resize(list->data, (size_t)list->capacity * sizeof *list->data);
    }
    list->data[list->count++] = step;
}
static CandidatePlan *read_candidates(int *count) {
    CandidatePlan *out = allocate(20 * sizeof *out);
    *count = 0;
    TextLines lines = read_lines("input/candidates.txt");
    for (int i = 0; i < lines.count; ++i) {
        char *line = lines.data[i];
        if (!line[0] || line[0] == '#')
            continue;
        if (!strncmp(line, "plan ", 5)) {
            IntList words = split_words(line);
            out[*count].problem = words.data[1];
            out[(*count)++].label = words.data[2];
            int_free(&words);
        } else if (strcmp(line, "end")) {
            line[strlen(line) - 1] = 0;
            IntList words = split_words(line + 1);
            Step step = {words.data[0], {0}};
            for (int j = 1; j < words.count; ++j)
                int_push(&step.arguments, words.data[j]);
            steps_push(&out[*count - 1].steps, step);
            int_free(&words);
        }
    }
    lines_free(&lines);
    return out;
}
static char *argument_check(const Domain *domain, const IntList *arguments, const IntList *expected,
                            const TypedList *types, const char *noun) {
    if (arguments->count != expected->count)
        return format_text("expected %d arguments, got %d", expected->count, arguments->count);
    for (int i = 0; i < arguments->count; ++i) {
        int argument = arguments->data[i], type = typed_find(types, argument);
        if (type < 0)
            return format_text("unknown %s %s", noun, symbol_name(argument));
        if (!subtype(domain, type, expected->data[i]))
            return format_text("argument %d (%s) is not of type %s", i + 1, symbol_name(argument),
                               symbol_name(expected->data[i]));
    }
    return NULL;
}
static void validate_domain(Domain *domain) {
    int kept = 0;
    for (int i = 0; i < domain->action_count; ++i) {
        Schema schema = domain->actions[i];
        char *reason = NULL;
        for (int j = 0; j < schema.parameters.count; ++j)
            if (!reason && !int_has(&domain->types, schema.parameters.data[j].type))
                reason =
                    format_text("unknown type %s", symbol_name(schema.parameters.data[j].type));
        for (int side = 0; side < 2 && !reason; ++side) {
            LiteralList *literals = side ? &schema.effects : &schema.conditions;
            for (int j = 0; j < literals->count; ++j) {
                int id = literals->data[j].atom;
                const Atom *atom = get_atom(id);
                IntList expected = {0};
                int equality[2] = {symbol("object"), symbol("object")};
                if (!strcmp(symbol_name(atom->predicate), "="))
                    expected = (IntList){equality, 2, 2};
                else {
                    int predicate = predicate_index(domain, atom->predicate);
                    if (predicate < 0) {
                        char *notation = atom_text(id);
                        reason = format_text("%s: unknown predicate %s", notation,
                                             symbol_name(atom->predicate));
                        free(notation);
                        break;
                    }
                    expected = domain->predicates[predicate].types;
                }
                char *error =
                    argument_check(domain, &atom->terms, &expected, &schema.parameters, "variable");
                if (error) {
                    char *notation = atom_text(id);
                    reason = format_text("%s: %s", notation, error);
                    free(notation);
                    free(error);
                    break;
                }
            }
        }
        if (reason) {
            lines_push(&domain->diagnostics,
                       format_text("error: action %s: %s", symbol_name(schema.name), reason));
            free(reason);
            free(schema.parameters.data);
            free(schema.conditions.data);
            free(schema.effects.data);
        } else
            domain->actions[kept++] = schema;
    }
    domain->action_count = kept;
    IntList used = {0};
    for (int i = 0; i < kept; ++i) {
        const Schema *schema = &domain->actions[i];
        for (int j = 0; j < schema->conditions.count; ++j)
            int_add(&used, get_atom(schema->conditions.data[j].atom)->predicate);
        for (int j = 0; j < schema->effects.count; ++j)
            int_add(&used, get_atom(schema->effects.data[j].atom)->predicate);
    }
    for (int i = 0; i < domain->predicate_count; ++i)
        if (!int_has(&used, domain->predicates[i].name))
            lines_push(&domain->diagnostics,
                       format_text("warning: predicate %s is not used by any action",
                                   symbol_name(domain->predicates[i].name)));
    int_free(&used);
    classify(domain);
}
static void validate_atoms(const Domain *domain, Problem *problem, IntList *atoms,
                           const char *side) {
    IntList kept = {0};
    for (int i = 0; i < atoms->count; ++i) {
        int id = atoms->data[i];
        const Atom *atom = get_atom(id);
        int predicate = predicate_index(domain, atom->predicate);
        char *reason = NULL;
        if (predicate < 0)
            reason = format_text("unknown predicate %s", symbol_name(atom->predicate));
        else
            reason = argument_check(domain, &atom->terms, &domain->predicates[predicate].types,
                                    &problem->objects, "object");
        if (!reason && int_has(&kept, id))
            reason = copy_text("duplicate");
        if (reason) {
            char *notation = atom_text(id);
            lines_push(&problem->diagnostics,
                       format_text("warning: %s %s: %s", side, notation, reason));
            free(notation);
            free(reason);
        } else
            int_push(&kept, id);
    }
    int_free(atoms);
    *atoms = kept;
}
static void validate_problem(const Domain *domain, Problem *problem) {
    validate_atoms(domain, problem, &problem->initial, "init");
    validate_atoms(domain, problem, &problem->goals, "goal");
}
static TextLines domain_lines(const Domain *domain) {
    TextLines out = {0};
    lines_push(&out, format_text("== domain %s ==", symbol_name(domain->name)));
    lines_append(&out, &domain->diagnostics);
    int object = symbol("object");
    for (int i = 0; i < domain->types.count; ++i) {
        int type = domain->types.data[i];
        IntList chain = {0};
        int_push(&chain, type);
        while (type != object) {
            type = typed_find(&domain->parents, type);
            int_push(&chain, type);
        }
        char *joined = join_words(&chain, " < ");
        lines_push(&out, format_text("type %s", joined));
        free(joined);
        int_free(&chain);
    }
    for (int i = 0; i < domain->predicate_count; ++i)
        lines_push(&out, format_text("predicate %s/%d %s", symbol_name(domain->predicates[i].name),
                                     domain->predicates[i].types.count,
                                     domain->fluent[i] ? "fluent" : "static"));
    for (int i = 0; i < domain->action_count; ++i) {
        const Schema *schema = &domain->actions[i];
        int adds = 0, deletes = 0;
        for (int j = 0; j < schema->effects.count; ++j) {
            if (schema->effects.data[j].negative)
                ++deletes;
            else
                ++adds;
        }
        lines_push(&out, format_text("action %s/%d cost=%lld pre=%d add=%d del=%d",
                                     symbol_name(schema->name), schema->parameters.count,
                                     schema->cost, schema->conditions.count, adds, deletes));
    }
    return out;
}
static TextLines grounding_lines(const GroundProblem *ground) {
    const Domain *domain = ground->domain;
    const Problem *problem = ground->problem;
    TextLines out = {0};
    lines_push(&out, format_text("== problem %s ==", symbol_name(problem->name)));
    lines_append(&out, &problem->diagnostics);
    lines_push(&out, format_text("objects: %d", problem->objects.count));
    for (int i = 0; i < domain->types.count; ++i) {
        IntList objects = objects_of_type(domain, problem, domain->types.data[i]);
        TextLines names = {0};
        for (int j = 0; j < objects.count; ++j)
            lines_add(&names, symbol_name(objects.data[j]));
        char *name = format_text("  %s:", symbol_name(domain->types.data[i]));
        lines_push(&out, heading(name, &names));
        free(name);
        lines_free(&names);
        int_free(&objects);
    }
    lines_push(&out, format_text("static facts: %d", ground->static_facts));
    for (int i = 0; i < domain->action_count; ++i) {
        const SchemaCount *count = &ground->counts[i];
        lines_push(&out, format_text("schema %s: assignments=%d candidates=%d reachable=%d",
                                     symbol_name(domain->actions[i].name), count->assignments,
                                     count->candidates, count->reachable));
    }
    lines_push(&out, format_text("candidates: %d reachable: %d", ground->candidate_count,
                                 ground->action_count));
    lines_push(&out, format_text("facts: %d init: %d goals: %d", ground->facts.count,
                                 state_count(ground->initial), state_count(ground->goal)));
    for (int i = 0; i < ground->unreachable.count; ++i) {
        char *atom = atom_text(ground->unreachable.data[i]);
        lines_push(&out, format_text("unreachable goal: %s", atom));
        free(atom);
    }
    int counts[15] = {0};
    for (int i = 0; i < ground->facts.count; ++i)
        ++counts[predicate_index(domain, get_atom(ground->facts.data[i])->predicate)];
    TextLines items = {0};
    for (int i = 0; i < domain->predicate_count; ++i)
        if (domain->fluent[i])
            lines_push(&items,
                       format_text("%s=%d", symbol_name(domain->predicates[i].name), counts[i]));
    lines_push(&out, heading("facts by predicate:", &items));
    lines_free(&items);
    lines_add(&out, "facts:");
    for (int i = 0; i < ground->facts.count; ++i) {
        char *atom = atom_text(ground->facts.data[i]);
        lines_push(&out, format_text("  %d %s", i, atom));
        free(atom);
    }
    lines_add(&out, "actions:");
    for (int i = 0; i < ground->action_count; ++i) {
        const GroundAction *action = &ground->actions[i];
        char *notation = action_text(ground, i), *pre = number_list(action->pre),
             *neg = number_list(action->neg), *add = number_list(action->add),
             *del = number_list(action->del);
        lines_push(&out, format_text("  %d %s cost=%lld pre=%s neg=%s add=%s del=%s", i, notation,
                                     action->cost, pre, neg, add, del));
        free(notation);
        free(pre);
        free(neg);
        free(add);
        free(del);
    }
    return out;
}
typedef struct {
    const char *status;
    TextLines messages;
    int correct;
} Validation;
static char *verdict(const Validation *validation) {
    return format_text("%s%s%s", validation->status,
                       !strcmp(validation->status, "valid") ? " " : ": ",
                       validation->messages.data[0]);
}
static Validation validate_steps(const Domain *domain, const Problem *problem,
                                 const StepList *steps) {
    Validation out = {0};
    IntList world = int_copy(&problem->initial);
    Value cost = 0;
    for (int i = 0; i < steps->count; ++i) {
        const Step *step = &steps->data[i];
        char *notation = step_text(step), *prefix = format_text("step %d %s: ", i + 1, notation);
        free(notation);
        const Schema *schema = NULL;
        for (int j = 0; j < domain->action_count; ++j)
            if (domain->actions[j].name == step->name) {
                schema = &domain->actions[j];
                break;
            }
        char *reason = NULL;
        if (!schema)
            reason = format_text("unknown action %s", symbol_name(step->name));
        else {
            IntList expected = {0};
            for (int j = 0; j < schema->parameters.count; ++j)
                int_push(&expected, schema->parameters.data[j].type);
            reason =
                argument_check(domain, &step->arguments, &expected, &problem->objects, "object");
            int_free(&expected);
        }
        TypedList assignment = {0};
        if (!reason) {
            assignment.count = assignment.capacity = schema->parameters.count;
            assignment.data = allocate((size_t)assignment.count * sizeof *assignment.data);
            for (int j = 0; j < assignment.count; ++j)
                assignment.data[j] =
                    (Typed){schema->parameters.data[j].name, step->arguments.data[j]};
            for (int j = 0; j < schema->conditions.count; ++j) {
                Literal literal = schema->conditions.data[j];
                literal.atom = substitute_atom(literal.atom, &assignment);
                const Atom *atom = get_atom(literal.atom);
                bool truth = !strcmp(symbol_name(atom->predicate), "=")
                                 ? atom->terms.data[0] == atom->terms.data[1]
                                 : int_has(&world, literal.atom);
                if (truth == literal.negative) {
                    char *literal_notation = literal_text(literal);
                    reason = format_text("precondition %s is false", literal_notation);
                    free(literal_notation);
                    break;
                }
            }
        }
        if (reason) {
            out.status = "invalid";
            out.correct = i;
            lines_push(&out.messages, format_text("%s%s", prefix, reason));
            free(prefix);
            free(reason);
            free(assignment.data);
            int_free(&world);
            return out;
        }
        for (int j = 0; j < schema->effects.count; ++j)
            if (schema->effects.data[j].negative) {
                int id = substitute_atom(schema->effects.data[j].atom, &assignment), kept = 0;
                for (int k = 0; k < world.count; ++k)
                    if (world.data[k] != id)
                        world.data[kept++] = world.data[k];
                world.count = kept;
            }
        for (int j = 0; j < schema->effects.count; ++j)
            if (!schema->effects.data[j].negative)
                int_add(&world, substitute_atom(schema->effects.data[j].atom, &assignment));
        cost += schema->cost;
        free(assignment.data);
        free(prefix);
    }
    out.correct = steps->count;
    for (int i = 0; i < problem->goals.count; ++i)
        if (!int_has(&world, problem->goals.data[i])) {
            char *atom = atom_text(problem->goals.data[i]);
            lines_push(&out.messages, format_text("unsatisfied goal %s", atom));
            free(atom);
        }
    int_free(&world);
    if (out.messages.count)
        out.status = "goal not reached";
    else {
        out.status = "valid";
        lines_push(&out.messages, format_text("length=%d cost=%lld", steps->count, cost));
    }
    return out;
}
static Validation validate_plan(const GroundProblem *ground, const IntList *plan) {
    StepList steps = {0};
    for (int i = 0; i < plan->count; ++i) {
        const GroundAction *action = &ground->actions[plan->data[i]];
        steps_push(&steps, (Step){ground->domain->actions[action->schema].name, action->arguments});
    }
    Validation out = validate_steps(ground->domain, ground->problem, &steps);
    free(steps.data);
    return out;
}
static IntList map_steps(const GroundProblem *ground, const StepList *steps, int count) {
    IntList out = {0};
    for (int i = 0; i < count; ++i) {
        for (int j = 0; j < ground->action_count; ++j) {
            const GroundAction *action = &ground->actions[j];
            const Step *step = &steps->data[i];
            if (ground->domain->actions[action->schema].name == step->name &&
                action->arguments.count == step->arguments.count &&
                (!step->arguments.count ||
                 !memcmp(action->arguments.data, step->arguments.data,
                         (size_t)step->arguments.count * sizeof *step->arguments.data))) {
                int_push(&out, j);
                break;
            }
        }
    }
    return out;
}
static Value plan_cost(const GroundProblem *ground, const IntList *plan) {
    Value cost = 0;
    for (int i = 0; i < plan->count; ++i)
        cost += ground->actions[plan->data[i]].cost;
    return cost;
}
static IntList improve(const GroundProblem *ground, const IntList *source) {
    IntList plan = int_copy(source);
    for (int at = 0; at < plan.count;) {
        State state = ground->initial;
        IntList kept = {0};
        for (int i = 0; i < at; ++i) {
            state = apply(&ground->actions[plan.data[i]], state);
            int_push(&kept, plan.data[i]);
        }
        for (int i = at + 1; i < plan.count; ++i)
            if (applicable(&ground->actions[plan.data[i]], state)) {
                state = apply(&ground->actions[plan.data[i]], state);
                int_push(&kept, plan.data[i]);
            }
        if (state_contains(state, ground->goal)) {
            int_free(&plan);
            plan = kept;
        } else {
            int_free(&kept);
            ++at;
        }
    }
    return plan;
}
static bool interfere(const GroundAction *a, const GroundAction *b) {
    return state_intersects(a->del, state_union(b->pre, b->add)) ||
           state_intersects(b->del, state_union(a->pre, a->add)) ||
           state_intersects(a->add, b->neg) || state_intersects(b->add, a->neg);
}
static Layers parallelize(const GroundProblem *ground, const IntList *plan) {
    int *layer = allocate((size_t)plan->count * sizeof *layer), count = 0;
    for (int j = 0; j < plan->count; ++j) {
        layer[j] = 1;
        const GroundAction *action = &ground->actions[plan->data[j]];
        for (int i = 0; i < j; ++i) {
            const GroundAction *previous = &ground->actions[plan->data[i]];
            if ((state_intersects(previous->add, action->pre) ||
                 state_intersects(previous->del, action->neg) || interfere(previous, action)) &&
                layer[i] + 1 > layer[j])
                layer[j] = layer[i] + 1;
        }
        if (layer[j] > count)
            count = layer[j];
    }
    Layers out = {0};
    for (int i = 0; i < count; ++i)
        layers_push(&out, (IntList){0});
    for (int i = 0; i < plan->count; ++i)
        int_push(&out.data[layer[i] - 1], plan->data[i]);
    free(layer);
    return out;
}
static char *parallel_validation(const GroundProblem *ground, const Layers *layers) {
    State state = ground->initial;
    for (int k = 0; k < layers->count; ++k) {
        const IntList *layer = &layers->data[k];
        State adds = {0}, deletes = {0};
        for (int i = 0; i < layer->count; ++i) {
            const GroundAction *action = &ground->actions[layer->data[i]];
            if (!applicable(action, state))
                return format_text("invalid at layer %d", k + 1);
            for (int j = i + 1; j < layer->count; ++j)
                if (interfere(action, &ground->actions[layer->data[j]]))
                    return format_text("invalid at layer %d", k + 1);
            adds = state_union(adds, action->add);
            deletes = state_union(deletes, action->del);
        }
        state = state_union(state_without(state, deletes), adds);
    }
    return copy_text(state_contains(state, ground->goal) ? "valid" : "goal not reached");
}
static int transformed_graph(const GroundProblem *ground, GraphElement *actions, State *initial) {
    State negative = {0};
    for (int i = 0; i < ground->action_count; ++i)
        negative = state_union(negative, ground->actions[i].neg);
    int complement[100], count = 0;
    for (int fact = 0; fact < ground->facts.count; ++fact)
        complement[fact] = state_has(negative, fact) ? ground->facts.count + count++ : -1;
    *initial = ground->initial;
    for (int fact = 0; fact < ground->facts.count; ++fact)
        if (complement[fact] >= 0 && !state_has(*initial, fact))
            state_put(initial, complement[fact]);
    for (int i = 0; i < ground->action_count; ++i) {
        const GroundAction *action = &ground->actions[i];
        actions[i] = (GraphElement){i, -1, action->pre, action->add, action->del};
        for (int fact = 0; fact < ground->facts.count; ++fact) {
            if (state_has(action->neg, fact))
                state_put(&actions[i].pre, complement[fact]);
            if (complement[fact] >= 0) {
                if (state_has(action->del, fact))
                    state_put(&actions[i].add, complement[fact]);
                if (state_has(action->add, fact))
                    state_put(&actions[i].del, complement[fact]);
            }
        }
    }
    return count;
}
static char *heuristic_text(Value value) {
    return value == INFINITY_VALUE ? copy_text("inf") : format_text("%lld", value);
}
static char *heuristic_values(const Heuristic *heuristic) {
    TextLines items = {0};
    for (int i = 0; i < 5; ++i) {
        char *value = heuristic_text(heuristic_value(heuristic, heuristic_names[i]));
        lines_push(&items, format_text("%s=%s", heuristic_names[i], value));
        free(value);
    }
    char *out = join_texts(&items, " ");
    lines_free(&items);
    return out;
}
typedef struct {
    SearchSettings settings;
    char *tag;
    SearchResult result;
} RunRecord;
typedef struct {
    GroundProblem *ground;
    RunRecord runs[13];
    int run_count, proof, solved;
    GraphPlanResult graph;
    Value best;
    char *optimal;
} ProblemResult;
typedef struct {
    TextLines plans, graph, validation, comparison;
    int validated, valid_plans;
} Output;
typedef struct {
    const IntList *plan;
    const char *tag;
} SeenPlan;
static bool same_plan(const IntList *a, const IntList *b) {
    return a->count == b->count &&
           (!a->count || !memcmp(a->data, b->data, (size_t)a->count * sizeof *a->data));
}
static void plan_block(GroundProblem *ground, const char *tag, const IntList *plan, SeenPlan *seen,
                       int *seen_count, Output *output) {
    const char *earlier = NULL;
    for (int i = 0; i < *seen_count; ++i)
        if (same_plan(seen[i].plan, plan)) {
            earlier = seen[i].tag;
            break;
        }
    if (earlier)
        lines_push(&output->plans, format_text("plan: length=%d cost=%lld (same as %s)",
                                               plan->count, plan_cost(ground, plan), earlier));
    else {
        lines_push(&output->plans,
                   format_text("plan: length=%d cost=%lld", plan->count, plan_cost(ground, plan)));
        seen[(*seen_count)++] = (SeenPlan){plan, tag};
    }
    int counts[10] = {0};
    for (int i = 0; i < plan->count; ++i) {
        ++counts[ground->actions[plan->data[i]].schema];
        char *action = action_text(ground, plan->data[i]);
        lines_push(&output->plans, format_text("  %d %s", i + 1, action));
        free(action);
    }
    TextLines items = {0};
    for (int i = 0; i < ground->domain->action_count; ++i)
        if (counts[i])
            lines_push(&items, format_text("%s=%d", symbol_name(ground->domain->actions[i].name),
                                           counts[i]));
    lines_push(&output->plans, heading("schemas:", &items));
    lines_free(&items);
    Layers layers = parallelize(ground, plan);
    lines_push(&output->plans, format_text("parallel: layers=%d", layers.count));
    for (int i = 0; i < layers.count; ++i) {
        items = action_texts(ground, &layers.data[i]);
        char *name = format_text("  %d:", i + 1);
        lines_push(&output->plans, heading(name, &items));
        free(name);
        lines_free(&items);
    }
    IntList improved = improve(ground, plan);
    int removed = plan->count - improved.count;
    lines_push(&output->plans, format_text("improved: length=%d cost=%lld removed=%d",
                                           improved.count, plan_cost(ground, &improved), removed));
    if (removed)
        for (int i = 0; i < improved.count; ++i) {
            char *action = action_text(ground, improved.data[i]);
            lines_push(&output->plans, format_text("  %d %s", i + 1, action));
            free(action);
        }
    State landmarks = heuristics(ground, ground->initial)->landmarks, reached = {0},
          state = ground->initial;
    for (int i = 0; i < plan->count; ++i) {
        state = apply(&ground->actions[plan->data[i]], state);
        reached = state_union(reached, state_intersection(state, landmarks));
    }
    lines_push(&output->plans, format_text("landmarks reached: %d/%d", state_count(reached),
                                           state_count(landmarks)));
    for (int i = 0; i < ground->facts.count; ++i)
        if (state_has(landmarks, i) && !state_has(reached, i)) {
            char *atom = atom_text(ground->facts.data[i]);
            lines_push(&output->plans, format_text("  missed %s", atom));
            free(atom);
        }
    Validation original = validate_plan(ground, plan), better = validate_plan(ground, &improved);
    char *original_verdict = verdict(&original), *better_verdict = verdict(&better),
         *parallel = parallel_validation(ground, &layers);
    ++output->validated;
    if (!strcmp(original.status, "valid"))
        ++output->valid_plans;
    lines_push(&output->validation, format_text("%s: %s", tag, original_verdict));
    lines_push(&output->validation, format_text("  parallel: %s", parallel));
    lines_push(&output->validation, format_text("  improved: %s", better_verdict));
    free(original_verdict);
    free(better_verdict);
    free(parallel);
    lines_free(&original.messages);
    lines_free(&better.messages);
    int_free(&improved);
    layers_free(&layers);
}
static TextLines profile(GroundProblem *ground, const RunRecord *proof) {
    const IntList *plan = &proof->result.plan;
    TextLines out = {0};
    lines_push(&out, format_text("-- profile (%s) --", proof->tag));
    Value remaining = plan_cost(ground, plan);
    State state = ground->initial;
    int overestimates[5] = {0};
    for (int i = 0; i <= plan->count; ++i) {
        Heuristic *estimate = heuristics(ground, state);
        char *values = heuristic_values(estimate);
        lines_push(&out, format_text("  %d: h*=%lld %s", i, remaining, values));
        free(values);
        for (int j = 0; j < 5; ++j)
            if (heuristic_value(estimate, heuristic_names[j]) > remaining)
                ++overestimates[j];
        if (i < plan->count) {
            remaining -= ground->actions[plan->data[i]].cost;
            state = apply(&ground->actions[plan->data[i]], state);
        }
    }
    TextLines counts = {0};
    for (int i = 0; i < 5; ++i)
        lines_push(&counts, format_text("%s=%d", heuristic_names[i], overestimates[i]));
    char *joined = join_texts(&counts, " ");
    lines_push(&out, format_text("overestimates: %s", joined));
    free(joined);
    lines_free(&counts);
    lines_push(&out, format_text("-- causal links (%s) --", proof->tag));
    int supplier[100] = {0};
    for (int i = 0; i < plan->count; ++i) {
        const GroundAction *action = &ground->actions[plan->data[i]];
        TextLines items = {0};
        for (int fact = 0; fact < ground->facts.count; ++fact)
            if (state_has(action->pre, fact)) {
                char *atom = atom_text(ground->facts.data[fact]);
                lines_push(&items, format_text("%s<-%d", atom, supplier[fact]));
                free(atom);
            }
        char *notation = action_text(ground, plan->data[i]),
             *name = format_text("  %d %s:", i + 1, notation);
        lines_push(&out, heading(name, &items));
        free(notation);
        free(name);
        lines_free(&items);
        for (int fact = 0; fact < ground->facts.count; ++fact)
            if (state_has(action->add, fact))
                supplier[fact] = i + 1;
    }
    TextLines items = {0};
    for (int fact = 0; fact < ground->facts.count; ++fact)
        if (state_has(ground->goal, fact)) {
            char *atom = atom_text(ground->facts.data[fact]);
            lines_push(&items, format_text("%s<-%d", atom, supplier[fact]));
            free(atom);
        }
    lines_push(&out, heading("  goal:", &items));
    lines_free(&items);
    return out;
}
static char *result_line(const SearchResult *result) {
    if (!strcmp(result->status, "unreachable goal"))
        return copy_text("result: FAIL (unreachable goal)");
    if (!strcmp(result->status, "solved"))
        return format_text("result: solved expanded=%lld generated=%lld", result->expanded,
                           result->generated);
    return format_text("result: FAIL (%s) expanded=%lld generated=%lld", result->status,
                       result->expanded, result->generated);
}
static ProblemResult process_problem(GroundProblem *ground, const Settings *settings,
                                     Output *output) {
    ProblemResult out = {0};
    out.ground = ground;
    out.best = -1;
    out.proof = -1;
    out.optimal = copy_text("unknown");
    char *title = format_text("== problem %s ==", symbol_name(ground->problem->name));
    lines_add(&output->plans, title);
    lines_add(&output->graph, title);
    lines_push(&output->validation, title);
    bool unreachable = ground->unreachable.count != 0;
    if (unreachable)
        lines_add(&output->plans, "initial h: unreachable goal");
    else {
        Heuristic *estimate = heuristics(ground, ground->initial);
        char *values = heuristic_values(estimate);
        lines_push(&output->plans, format_text("initial h: %s", values));
        free(values);
        lines_push(&output->plans, format_text("landmarks: %d", state_count(estimate->landmarks)));
        for (int fact = 0; fact < ground->facts.count; ++fact)
            if (state_has(estimate->landmarks, fact)) {
                char *atom = atom_text(ground->facts.data[fact]);
                lines_push(&output->plans, format_text("  %s", atom));
                free(atom);
            }
        char *ff = heuristic_text(estimate->ff);
        lines_push(&output->plans,
                   format_text("relaxed plan: length=%d cost=%s", estimate->relaxed.count, ff));
        free(ff);
        for (int i = 0; i < estimate->relaxed.count; ++i) {
            char *action = action_text(ground, estimate->relaxed.data[i]);
            lines_push(&output->plans, format_text("  %s", action));
            free(action);
        }
        TextLines helpful = action_texts(ground, &estimate->helpful);
        lines_push(&output->plans, heading("helpful:", &helpful));
        lines_free(&helpful);
    }
    for (int i = 0; i < settings->run_count; ++i) {
        SearchSettings run = settings->runs[i];
        SearchResult result = {0};
        if (unreachable)
            result.status = "unreachable goal";
        else
            result = search(ground, ground->initial, run, settings->budget, settings->weight);
        char *tag = format_text("%s %s", run.algorithm, run.heuristic);
        if (out.proof < 0 && !strcmp(result.status, "solved") &&
            (!strcmp(tag, "ucs none") || !strcmp(tag, "astar hmax")))
            out.proof = out.run_count;
        out.runs[out.run_count++] = (RunRecord){run, tag, result};
    }
    if (unreachable) {
        out.graph.status = "unreachable goal";
        lines_add(&output->graph, "result: FAIL (unreachable goal)");
    } else {
        GraphElement actions[300];
        State initial;
        int count = transformed_graph(ground, actions, &initial);
        out.graph =
            graph_plan(actions, ground->action_count, initial, ground->goal, settings->level_limit);
        const GraphPlanResult *result = &out.graph;
        lines_push(&output->graph, format_text("complementary facts: %d", count));
        lines_append(&output->graph, &result->logs);
        if (!strcmp(result->status, "solved")) {
            lines_push(
                &output->graph,
                format_text(
                    "result: solved levels=%d length=%d cost=%lld searched=%lld memo_hits=%lld tried=%lld",
                    result->layers.count, result->plan.count, plan_cost(ground, &result->plan),
                    result->searched, result->memo_hits, result->tried));
            for (int i = 0; i < result->layers.count; ++i) {
                TextLines items = action_texts(ground, &result->layers.data[i]);
                char *name = format_text("layer %d:", i + 1);
                lines_push(&output->graph, heading(name, &items));
                free(name);
                lines_free(&items);
            }
        } else
            lines_push(&output->graph,
                       format_text("result: FAIL (%s) searched=%lld memo_hits=%lld tried=%lld",
                                   result->status, result->searched, result->memo_hits,
                                   result->tried));
    }
    out.runs[out.run_count++] =
        (RunRecord){{"graphplan", "none"},
                    copy_text("graphplan"),
                    (SearchResult){out.graph.status, int_copy(&out.graph.plan), out.graph.searched,
                                   out.graph.tried}};
    SeenPlan seen[13];
    int seen_count = 0;
    for (int i = 0; i < out.run_count; ++i) {
        const RunRecord *record = &out.runs[i];
        const SearchResult *result = &record->result;
        lines_push(&output->plans, format_text("-- %s --", record->tag));
        lines_push(&output->plans, result_line(result));
        char *length = copy_text("-"), *cost = copy_text("-");
        if (!strcmp(result->status, "solved")) {
            ++out.solved;
            Value value = plan_cost(ground, &result->plan);
            if (out.best < 0 || value < out.best)
                out.best = value;
            free(length);
            free(cost);
            length = format_text("%d", result->plan.count);
            cost = format_text("%lld", value);
            plan_block(ground, record->tag, &result->plan, seen, &seen_count, output);
        }
        lines_push(&output->comparison,
                   format_text("%s,%s,%s,%s,%s,%lld,%lld", symbol_name(ground->problem->name),
                               record->settings.algorithm, record->settings.heuristic, length, cost,
                               result->expanded, result->generated));
        free(length);
        free(cost);
    }
    if (out.proof >= 0) {
        free(out.optimal);
        out.optimal = format_text("%lld", plan_cost(ground, &out.runs[out.proof].result.plan));
        TextLines details = profile(ground, &out.runs[out.proof]);
        append_owned(&output->plans, &details);
    } else
        for (int i = 0; i < out.run_count; ++i) {
            const char *status = out.runs[i].result.status;
            if (!strcmp(status, "unreachable goal") || !strcmp(status, "dead end") ||
                !strcmp(status, "exhausted") || !strcmp(status, "unreachable")) {
                free(out.optimal);
                out.optimal = copy_text("none");
                break;
            }
        }
    lines_add(&output->plans, "");
    lines_add(&output->graph, "");
    lines_add(&output->validation, "");
    return out;
}
static char *best_text(Value value) {
    return value < 0 ? copy_text("-") : format_text("%lld", value);
}
static int candidate_lines(const Domain *domain, const CandidatePlan *candidates, int count,
                           ProblemResult *problems, int problem_count, const Settings *settings,
                           TextLines *out) {
    lines_add(out, "== candidates ==");
    int valid = 0;
    for (int i = 0; i < count; ++i) {
        const CandidatePlan *candidate = &candidates[i];
        ProblemResult *problem = NULL;
        for (int j = 0; j < problem_count; ++j)
            if (problems[j].ground->problem->name == candidate->problem) {
                problem = &problems[j];
                break;
            }
        GroundProblem *ground = problem->ground;
        Validation validation = validate_steps(domain, ground->problem, &candidate->steps);
        char *prefix = format_text("candidate %d %s %s: ", i + 1, symbol_name(candidate->problem),
                                   symbol_name(candidate->label));
        if (!strcmp(validation.status, "valid")) {
            ++valid;
            IntList plan = map_steps(ground, &candidate->steps, candidate->steps.count),
                    improved = improve(ground, &plan);
            char *result = verdict(&validation), *best = best_text(problem->best);
            lines_push(out, format_text("%s%s", prefix, result));
            lines_push(out, format_text("  improved: length=%d cost=%lld removed=%d best known=%s",
                                        improved.count, plan_cost(ground, &improved),
                                        candidate->steps.count - improved.count, best));
            free(prefix);
            free(result);
            free(best);
            int_free(&plan);
            int_free(&improved);
            lines_free(&validation.messages);
            continue;
        }
        lines_push(out, format_text("%s%s", prefix, validation.status));
        free(prefix);
        for (int j = 0; j < validation.messages.count; ++j)
            lines_push(out, format_text("  %s", validation.messages.data[j]));
        int correct = validation.correct;
        lines_free(&validation.messages);
        if (ground->unreachable.count) {
            lines_add(out, "  repair: FAIL (unreachable goal)");
            continue;
        }
        IntList plan = map_steps(ground, &candidate->steps, correct);
        State state = ground->initial;
        for (int j = 0; j < plan.count; ++j)
            state = apply(&ground->actions[plan.data[j]], state);
        SearchResult repair =
            search(ground, state, settings->repair, settings->budget, settings->weight);
        if (strcmp(repair.status, "solved")) {
            lines_push(out, format_text("  repair: FAIL (%s)", repair.status));
            int_free(&plan);
            int_free(&repair.plan);
            continue;
        }
        for (int j = 0; j < repair.plan.count; ++j)
            int_push(&plan, repair.plan.data[j]);
        Validation repaired = validate_plan(ground, &plan);
        char *result = verdict(&repaired);
        lines_push(
            out, format_text("  repair: kept=%d added=%d %s", correct, repair.plan.count, result));
        free(result);
        for (int j = 0; j < plan.count; ++j) {
            char *action = action_text(ground, plan.data[j]);
            lines_push(out, format_text("    %d %s", j + 1, action));
            free(action);
        }
        lines_free(&repaired.messages);
        int_free(&plan);
        int_free(&repair.plan);
    }
    return valid;
}
static void write_lines(const char *name, const TextLines *lines) {
    char *path = format_text("output/%s", name);
    FILE *output = fopen(path, "wb");
    free(path);
    if (!output)
        exit(EXIT_FAILURE);
    for (int i = 0; i < lines->count; ++i) {
        if (fputs(lines->data[i], output) == EOF || fputc('\n', output) == EOF)
            exit(EXIT_FAILURE);
    }
    if (fclose(output))
        exit(EXIT_FAILURE);
}
int main(void) {
    Domain domain = read_domain();
    validate_domain(&domain);
    int problem_count, candidate_count;
    Problem *raw = read_problems(&problem_count);
    Settings settings = read_settings();
    CandidatePlan *candidates = read_candidates(&candidate_count);
    TextLines grounding = domain_lines(&domain);
    Output output = {0};
    lines_add(&output.comparison, "problem,algorithm,heuristic,length,cost,expanded,generated");
    GroundProblem *grounds = allocate((size_t)problem_count * sizeof *grounds);
    ProblemResult *problems = allocate((size_t)problem_count * sizeof *problems);
    for (int i = 0; i < problem_count; ++i) {
        validate_problem(&domain, &raw[i]);
        grounds[i] = ground(&domain, &raw[i]);
        lines_add(&grounding, "");
        TextLines details = grounding_lines(&grounds[i]);
        append_owned(&grounding, &details);
        problems[i] = process_problem(&grounds[i], &settings, &output);
    }
    lines_add(&output.plans, "== summary ==");
    for (int i = 0; i < problem_count; ++i) {
        char *best = best_text(problems[i].best);
        lines_push(&output.plans, format_text("%s: solved=%d/%d best=%s optimal=%s",
                                              symbol_name(raw[i].name), problems[i].solved,
                                              problems[i].run_count, best, problems[i].optimal));
        free(best);
    }
    for (int i = 0; i < problems[0].run_count; ++i) {
        int solved = 0, best = 0;
        Value expanded = 0, generated = 0;
        for (int j = 0; j < problem_count; ++j) {
            const SearchResult *result = &problems[j].runs[i].result;
            expanded += result->expanded;
            generated += result->generated;
            if (!strcmp(result->status, "solved")) {
                ++solved;
                if (plan_cost(problems[j].ground, &result->plan) == problems[j].best)
                    ++best;
            }
        }
        lines_push(&output.plans,
                   format_text("%s: solved=%d best=%d expanded=%lld generated=%lld",
                               problems[0].runs[i].tag, solved, best, expanded, generated));
    }
    int valid_candidates = candidate_lines(&domain, candidates, candidate_count, problems,
                                           problem_count, &settings, &output.validation);
    lines_add(&output.validation, "");
    lines_add(&output.validation, "== summary ==");
    lines_push(&output.validation,
               format_text("plans: %d valid: %d", output.validated, output.valid_plans));
    lines_push(&output.validation,
               format_text("candidates: %d valid: %d", candidate_count, valid_candidates));
    mkdir("output", 0755);
    write_lines("grounding.txt", &grounding);
    write_lines("plans.txt", &output.plans);
    write_lines("graphplan.txt", &output.graph);
    write_lines("validation.txt", &output.validation);
    write_lines("comparison.csv", &output.comparison);
    for (int i = 0; i < candidate_count; ++i) {
        for (int j = 0; j < candidates[i].steps.count; ++j)
            int_free(&candidates[i].steps.data[j].arguments);
        free(candidates[i].steps.data);
    }
    free(candidates);
    for (int i = 0; i < problem_count; ++i) {
        for (int j = 0; j < problems[i].run_count; ++j) {
            free(problems[i].runs[j].tag);
            int_free(&problems[i].runs[j].result.plan);
        }
        graph_result_free(&problems[i].graph);
        free(problems[i].optimal);
        ground_free(&grounds[i]);
        problem_free(&raw[i]);
    }
    free(problems);
    free(grounds);
    free(raw);
    domain_free(&domain);
    lines_free(&grounding);
    lines_free(&output.plans);
    lines_free(&output.graph);
    lines_free(&output.validation);
    lines_free(&output.comparison);
    symbols_destroy();
    return 0;
}

#include "planner.h"
void *allocate(size_t size) {
    void *data = calloc(1, size ? size : 1);
    if (!data)
        exit(EXIT_FAILURE);
    return data;
}
void *resize(void *data, size_t size) {
    void *next = realloc(data, size ? size : 1);
    if (!next)
        exit(EXIT_FAILURE);
    return next;
}
char *copy_text(const char *text) {
    size_t size = strlen(text) + 1;
    char *out = allocate(size);
    memcpy(out, text, size);
    return out;
}
char *format_text(const char *format, ...) {
    va_list args, copy;
    va_start(args, format);
    va_copy(copy, args);
    int length = vsnprintf(NULL, 0, format, copy);
    va_end(copy);
    if (length < 0)
        exit(EXIT_FAILURE);
    char *out = allocate((size_t)length + 1);
    vsnprintf(out, (size_t)length + 1, format, args);
    va_end(args);
    return out;
}
void int_push(IntList *list, int value) {
    if (list->count == list->capacity) {
        list->capacity = list->capacity ? list->capacity * 2 : 8;
        list->data = resize(list->data, (size_t)list->capacity * sizeof *list->data);
    }
    list->data[list->count++] = value;
}
bool int_has(const IntList *list, int value) {
    for (int i = 0; i < list->count; ++i)
        if (list->data[i] == value)
            return true;
    return false;
}
void int_add(IntList *list, int value) {
    if (!int_has(list, value))
        int_push(list, value);
}
IntList int_copy(const IntList *list) {
    IntList out = {0};
    if (list->count) {
        out.count = out.capacity = list->count;
        out.data = allocate((size_t)out.count * sizeof *out.data);
        memcpy(out.data, list->data, (size_t)out.count * sizeof *out.data);
    }
    return out;
}
void int_free(IntList *list) {
    free(list->data);
    *list = (IntList){0};
}
void lines_push(TextLines *lines, char *text) {
    if (lines->count == lines->capacity) {
        lines->capacity = lines->capacity ? lines->capacity * 2 : 16;
        lines->data = resize(lines->data, (size_t)lines->capacity * sizeof *lines->data);
    }
    lines->data[lines->count++] = text;
}
void lines_add(TextLines *lines, const char *text) { lines_push(lines, copy_text(text)); }
void lines_append(TextLines *lines, const TextLines *from) {
    for (int i = 0; i < from->count; ++i)
        lines_add(lines, from->data[i]);
}
void lines_free(TextLines *lines) {
    for (int i = 0; i < lines->count; ++i)
        free(lines->data[i]);
    free(lines->data);
    *lines = (TextLines){0};
}
TextLines read_lines(const char *path) {
    FILE *input = fopen(path, "rb");
    if (!input)
        exit(EXIT_FAILURE);
    TextLines out = {0};
    char *line = NULL;
    size_t length = 0, capacity = 0;
    int c;
    while ((c = fgetc(input)) != EOF) {
        if (c == '\n') {
            if (!line)
                line = allocate(1);
            line[length] = 0;
            lines_push(&out, line);
            line = NULL;
            length = capacity = 0;
        } else {
            if (length + 1 >= capacity) {
                capacity = capacity ? capacity * 2 : 128;
                line = resize(line, capacity);
            }
            line[length++] = (char)c;
        }
    }
    if (ferror(input))
        exit(EXIT_FAILURE);
    if (length) {
        line[length] = 0;
        lines_push(&out, line);
    } else
        free(line);
    fclose(input);
    return out;
}
char *join_texts(const TextLines *texts, const char *separator) {
    size_t size = 1, separator_size = strlen(separator);
    for (int i = 0; i < texts->count; ++i)
        size += strlen(texts->data[i]) + (i ? separator_size : 0);
    char *out = allocate(size), *at = out;
    for (int i = 0; i < texts->count; ++i) {
        if (i) {
            memcpy(at, separator, separator_size);
            at += separator_size;
        }
        size_t length = strlen(texts->data[i]);
        memcpy(at, texts->data[i], length);
        at += length;
    }
    *at = 0;
    return out;
}
typedef struct {
    char *name;
    uint64_t hash;
} Symbol;
static Symbol *symbols;
static int symbol_count, symbol_capacity, *symbol_slots, symbol_slot_count;
static Atom *atoms;
static int atom_count, atom_capacity, *atom_slots, atom_slot_count;
static uint64_t text_hash(const char *text) {
    uint64_t hash = UINT64_C(1469598103934665603);
    for (const unsigned char *p = (const unsigned char *)text; *p; ++p) {
        hash ^= *p;
        hash *= UINT64_C(1099511628211);
    }
    return hash;
}
static void rehash_symbols(int size) {
    free(symbol_slots);
    symbol_slots = allocate((size_t)size * sizeof *symbol_slots);
    symbol_slot_count = size;
    for (int i = 0; i < symbol_count; ++i) {
        int slot = (int)(symbols[i].hash & (uint64_t)(size - 1));
        while (symbol_slots[slot])
            slot = (slot + 1) & (size - 1);
        symbol_slots[slot] = i + 1;
    }
}
int symbol(const char *name) {
    if (!symbol_slot_count || (symbol_count + 1) * 10 > symbol_slot_count * 7)
        rehash_symbols(symbol_slot_count ? symbol_slot_count * 2 : 128);
    uint64_t hash = text_hash(name);
    int slot = (int)(hash & (uint64_t)(symbol_slot_count - 1));
    while (symbol_slots[slot]) {
        int id = symbol_slots[slot] - 1;
        if (symbols[id].hash == hash && !strcmp(symbols[id].name, name))
            return id;
        slot = (slot + 1) & (symbol_slot_count - 1);
    }
    if (symbol_count == symbol_capacity) {
        symbol_capacity = symbol_capacity ? symbol_capacity * 2 : 64;
        symbols = resize(symbols, (size_t)symbol_capacity * sizeof *symbols);
    }
    int id = symbol_count++;
    symbols[id] = (Symbol){copy_text(name), hash};
    symbol_slots[slot] = id + 1;
    return id;
}
const char *symbol_name(int id) { return symbols[id].name; }
IntList split_words(const char *text) {
    IntList out = {0};
    const char *at = text;
    while (*at) {
        while (*at == ' ' || *at == '\n')
            ++at;
        if (!*at)
            break;
        const char *start = at;
        while (*at && *at != ' ' && *at != '\n')
            ++at;
        size_t size = (size_t)(at - start);
        char *word = allocate(size + 1);
        memcpy(word, start, size);
        word[size] = 0;
        int_push(&out, symbol(word));
        free(word);
    }
    return out;
}
char *join_words(const IntList *words, const char *separator) {
    TextLines items = {0};
    for (int i = 0; i < words->count; ++i)
        lines_add(&items, symbol_name(words->data[i]));
    char *out = join_texts(&items, separator);
    lines_free(&items);
    return out;
}
static uint64_t atom_hash(int predicate, const IntList *terms) {
    uint64_t hash = (uint64_t)(unsigned)predicate + UINT64_C(1469598103934665603);
    for (int i = 0; i < terms->count; ++i) {
        hash ^= (uint64_t)(unsigned)terms->data[i] + 1;
        hash *= UINT64_C(1099511628211);
    }
    return hash;
}
static void rehash_atoms(int size) {
    free(atom_slots);
    atom_slots = allocate((size_t)size * sizeof *atom_slots);
    atom_slot_count = size;
    for (int i = 0; i < atom_count; ++i) {
        int slot = (int)(atom_hash(atoms[i].predicate, &atoms[i].terms) & (uint64_t)(size - 1));
        while (atom_slots[slot])
            slot = (slot + 1) & (size - 1);
        atom_slots[slot] = i + 1;
    }
}
int intern_atom(int predicate, const IntList *terms) {
    if (!atom_slot_count || (atom_count + 1) * 10 > atom_slot_count * 7)
        rehash_atoms(atom_slot_count ? atom_slot_count * 2 : 256);
    int slot = (int)(atom_hash(predicate, terms) & (uint64_t)(atom_slot_count - 1));
    while (atom_slots[slot]) {
        int id = atom_slots[slot] - 1;
        const Atom *atom = &atoms[id];
        if (atom->predicate == predicate && atom->terms.count == terms->count &&
            (!terms->count ||
             !memcmp(atom->terms.data, terms->data, (size_t)terms->count * sizeof *terms->data)))
            return id;
        slot = (slot + 1) & (atom_slot_count - 1);
    }
    if (atom_count == atom_capacity) {
        atom_capacity = atom_capacity ? atom_capacity * 2 : 128;
        atoms = resize(atoms, (size_t)atom_capacity * sizeof *atoms);
    }
    int id = atom_count++;
    atoms[id] = (Atom){predicate, int_copy(terms)};
    atom_slots[slot] = id + 1;
    return id;
}
const Atom *get_atom(int id) { return &atoms[id]; }
char *atom_text(int id) {
    const Atom *atom = get_atom(id);
    char *terms = join_words(&atom->terms, " ");
    char *out =
        format_text("(%s%s%s)", symbol_name(atom->predicate), atom->terms.count ? " " : "", terms);
    free(terms);
    return out;
}
char *literal_text(Literal literal) {
    char *atom = atom_text(literal.atom);
    if (!literal.negative)
        return atom;
    char *out = format_text("(not %s)", atom);
    free(atom);
    return out;
}
void symbols_destroy(void) {
    for (int i = 0; i < symbol_count; ++i)
        free(symbols[i].name);
    for (int i = 0; i < atom_count; ++i)
        int_free(&atoms[i].terms);
    free(symbols);
    free(symbol_slots);
    free(atoms);
    free(atom_slots);
}
typedef struct Expression {
    int word;
    struct Expression **list;
    int count, capacity;
} Expression;
static Expression *read_expression(const IntList *tokens, int *at) {
    int token = tokens->data[(*at)++];
    Expression *out = allocate(sizeof *out);
    out->word = token;
    if (strcmp(symbol_name(token), "("))
        return out;
    out->word = -1;
    while (strcmp(symbol_name(tokens->data[*at]), ")")) {
        if (out->count == out->capacity) {
            out->capacity = out->capacity ? out->capacity * 2 : 8;
            out->list = resize(out->list, (size_t)out->capacity * sizeof *out->list);
        }
        out->list[out->count++] = read_expression(tokens, at);
    }
    ++*at;
    return out;
}
static void expression_free(Expression *expression) {
    for (int i = 0; i < expression->count; ++i)
        expression_free(expression->list[i]);
    free(expression->list);
    free(expression);
}
static IntList tokens_from(const char *path) {
    TextLines lines = read_lines(path);
    IntList out = {0};
    for (int i = 0; i < lines.count; ++i) {
        char *at = lines.data[i];
        while (*at && *at != ';') {
            if (*at == ' ') {
                ++at;
                continue;
            }
            char *start = at;
            size_t length;
            if (*at == '(' || *at == ')') {
                ++at;
                length = 1;
            } else {
                while (*at && *at != ';' && *at != ' ' && *at != '(' && *at != ')')
                    ++at;
                length = (size_t)(at - start);
            }
            char saved = start[length];
            start[length] = 0;
            int_push(&out, symbol(start));
            start[length] = saved;
        }
    }
    lines_free(&lines);
    return out;
}
static IntList expression_words(const Expression *expression, int first) {
    IntList out = {0};
    for (int i = first; i < expression->count; ++i)
        int_push(&out, expression->list[i]->word);
    return out;
}
static void typed_push(TypedList *list, Typed value) {
    if (list->count == list->capacity) {
        list->capacity = list->capacity ? list->capacity * 2 : 8;
        list->data = resize(list->data, (size_t)list->capacity * sizeof *list->data);
    }
    list->data[list->count++] = value;
}
static TypedList typed_list(const IntList *tokens) {
    TypedList out = {0};
    IntList pending = {0};
    for (int i = 0; i < tokens->count; ++i) {
        if (!strcmp(symbol_name(tokens->data[i]), "-")) {
            int type = tokens->data[++i];
            for (int j = 0; j < pending.count; ++j)
                typed_push(&out, (Typed){pending.data[j], type});
            pending.count = 0;
        } else
            int_push(&pending, tokens->data[i]);
    }
    int object = symbol("object");
    for (int i = 0; i < pending.count; ++i)
        typed_push(&out, (Typed){pending.data[i], object});
    int_free(&pending);
    return out;
}
static int parse_atom(const Expression *expression) {
    IntList terms = expression_words(expression, 1);
    int out = intern_atom(expression->list[0]->word, &terms);
    int_free(&terms);
    return out;
}
static Literal parse_literal(const Expression *expression) {
    if (!strcmp(symbol_name(expression->list[0]->word), "not"))
        return (Literal){parse_atom(expression->list[1]), true};
    return (Literal){parse_atom(expression), false};
}
static void literal_push(LiteralList *list, Literal value) {
    if (list->count == list->capacity) {
        list->capacity = list->capacity ? list->capacity * 2 : 8;
        list->data = resize(list->data, (size_t)list->capacity * sizeof *list->data);
    }
    list->data[list->count++] = value;
}
static void read_literals(const Expression *expression, LiteralList *literals, Value *cost) {
    bool conjunction = !strcmp(symbol_name(expression->list[0]->word), "and");
    int count = conjunction ? expression->count - 1 : 1;
    for (int i = 0; i < count; ++i) {
        const Expression *entry = conjunction ? expression->list[i + 1] : expression;
        if (cost && !strcmp(symbol_name(entry->list[0]->word), "increase"))
            *cost = strtoll(symbol_name(entry->list[2]->word), NULL, 10);
        else
            literal_push(literals, parse_literal(entry));
    }
}
Domain read_domain(void) {
    IntList tokens = tokens_from("input/domain.txt");
    int at = 0;
    Expression *root = read_expression(&tokens, &at);
    int_free(&tokens);
    Domain out = {0};
    out.name = root->list[1]->list[1]->word;
    int object = symbol("object");
    int_push(&out.types, object);
    for (int i = 2; i < root->count; ++i) {
        const Expression *section = root->list[i];
        const char *kind = symbol_name(section->list[0]->word);
        if (!strcmp(kind, ":types")) {
            IntList words = expression_words(section, 1);
            for (int j = 0; j < words.count; ++j)
                if (strcmp(symbol_name(words.data[j]), "-") &&
                    !int_has(&out.types, words.data[j])) {
                    int_push(&out.types, words.data[j]);
                    typed_push(&out.parents, (Typed){words.data[j], object});
                }
            TypedList declared = typed_list(&words);
            for (int j = 0; j < declared.count; ++j)
                for (int k = 0; k < out.parents.count; ++k)
                    if (declared.data[j].name == out.parents.data[k].name)
                        out.parents.data[k].type = declared.data[j].type;
            int_free(&words);
            free(declared.data);
        } else if (!strcmp(kind, ":predicates")) {
            for (int j = 1; j < section->count; ++j) {
                const Expression *entry = section->list[j];
                Predicate *predicate = &out.predicates[out.predicate_count++];
                predicate->name = entry->list[0]->word;
                IntList words = expression_words(entry, 1);
                TypedList types = typed_list(&words);
                for (int k = 0; k < types.count; ++k)
                    int_push(&predicate->types, types.data[k].type);
                int_free(&words);
                free(types.data);
            }
        } else if (!strcmp(kind, ":action")) {
            Schema *schema = &out.actions[out.action_count++];
            schema->name = section->list[1]->word;
            schema->cost = 1;
            for (int j = 2; j < section->count; j += 2) {
                const char *field = symbol_name(section->list[j]->word);
                const Expression *value = section->list[j + 1];
                if (!strcmp(field, ":parameters")) {
                    IntList words = expression_words(value, 0);
                    schema->parameters = typed_list(&words);
                    int_free(&words);
                } else if (!strcmp(field, ":precondition"))
                    read_literals(value, &schema->conditions, NULL);
                else if (!strcmp(field, ":effect"))
                    read_literals(value, &schema->effects, &schema->cost);
            }
        }
    }
    expression_free(root);
    return out;
}
Problem *read_problems(int *count) {
    IntList tokens = tokens_from("input/problems.txt");
    int at = 0;
    Problem *out = allocate(8 * sizeof *out);
    *count = 0;
    while (at < tokens.count) {
        Expression *root = read_expression(&tokens, &at);
        Problem *problem = &out[(*count)++];
        problem->name = root->list[1]->list[1]->word;
        for (int i = 2; i < root->count; ++i) {
            const Expression *section = root->list[i];
            const char *kind = symbol_name(section->list[0]->word);
            if (!strcmp(kind, ":objects")) {
                IntList words = expression_words(section, 1);
                problem->objects = typed_list(&words);
                int_free(&words);
            } else if (!strcmp(kind, ":init"))
                for (int j = 1; j < section->count; ++j)
                    int_push(&problem->initial, parse_atom(section->list[j]));
            else if (!strcmp(kind, ":goal")) {
                const Expression *value = section->list[1];
                if (!strcmp(symbol_name(value->list[0]->word), "and"))
                    for (int j = 1; j < value->count; ++j)
                        int_push(&problem->goals, parse_atom(value->list[j]));
                else
                    int_push(&problem->goals, parse_atom(value));
            }
        }
        expression_free(root);
    }
    int_free(&tokens);
    return out;
}
void domain_free(Domain *domain) {
    int_free(&domain->types);
    free(domain->parents.data);
    for (int i = 0; i < domain->predicate_count; ++i)
        int_free(&domain->predicates[i].types);
    for (int i = 0; i < domain->action_count; ++i) {
        free(domain->actions[i].parameters.data);
        free(domain->actions[i].conditions.data);
        free(domain->actions[i].effects.data);
    }
    lines_free(&domain->diagnostics);
}
void problem_free(Problem *problem) {
    free(problem->objects.data);
    int_free(&problem->initial);
    int_free(&problem->goals);
    lines_free(&problem->diagnostics);
}

#ifndef PLANNER_H
#define PLANNER_H
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <sys/stat.h>
typedef long long Value;
#define INFINITY_VALUE (1LL << 60)
typedef struct {
    int *data;
    int count, capacity;
} IntList;
typedef struct {
    char **data;
    int count, capacity;
} TextLines;
typedef struct {
    uint64_t words[4];
} State;
typedef struct {
    int name, type;
} Typed;
typedef struct {
